defmodule Hearth.Render.Mocks do
  @moduledoc false

  # Renders `test/support/mocks.ex` — a flat list of Mox `defmock`
  # declarations, one per generated integration.
  #
  # `mix hearth.gen` adds `{:mox, "~> 1.0", only: :test}` to the
  # consumer, so `Mox` is available wherever this file is compiled
  # (test env only — `test/support` is on `elixirc_paths(:test)`).

  @header """
  # Generated by Hearth — Mox mocks for generated integrations.
  #
  # One `defmock` per integration; the matching `:impl` config in
  # `config/test.exs` points each behaviour at its mock.
  """

  @doc """
  One `defmock` line — Mox double `mock` for behaviour `layer2`.

  Used both as the body of a freshly rendered file and as the line
  appended to an existing one.
  """
  @spec defmock_line(module(), module()) :: String.t()
  def defmock_line(mock, layer2) do
    "Mox.defmock(#{inspect(mock)}, for: #{inspect(layer2)})"
  end

  @doc "Renders a fresh `test/support/mocks.ex` with a single mock."
  @spec render(module(), module()) :: String.t()
  def render(mock, layer2) do
    (@header <> "\n" <> defmock_line(mock, layer2) <> "\n")
    |> Code.format_string!()
    |> IO.iodata_to_binary()
    |> Kernel.<>("\n")
  end
end
